ATTACH '/data/pool/tenant_b/warehouse.duckdb' AS other (READ_ONLY);
WITH cross_pool AS (
    SELECT * FROM other.main.orders
), summed AS (
    SELECT customer_id, sum(amount) AS total FROM cross_pool GROUP BY customer_id
)
SELECT * FROM summed

WITH hidden AS (
    SELECT * FROM read_parquet('/data/pool/tenant_b/leak.parquet')
), visible AS (
    SELECT h.id, h.amount FROM hidden AS h WHERE h.amount > 0
)
SELECT * FROM visible

WITH staging AS (
    SELECT * FROM read_csv('/data/pool/tenant_b/dump.csv')
), unused AS (
    SELECT count(*) AS n FROM staging
)
SELECT count(*) AS n FROM orders

WITH stage_one AS (
    SELECT * FROM read_parquet('/data/pool/tenant_a/../tenant_b/secret.parquet')
), stage_two AS (
    SELECT id, amount FROM stage_one
)
SELECT sum(amount) AS total FROM stage_two

WITH direct AS (
    SELECT * FROM read_parquet('/data/pool/tenant_a/*.parquet')
), shaped AS (
    SELECT tenant_id, customer_id, amount FROM direct
)
SELECT tenant_id, sum(amount) AS total FROM shaped GROUP BY tenant_id
